1	use std::collections::HashMap;
2	
3	/// Added to every premium, whatever the policy contains.
4	const PROCESSING_FEE: u64 = 5;
5	
6	/// Charged once per component, uniformly for every component type.
7	const COMPONENT_BASE_PREMIUM: u64 = 25;
8	
9	/// Components alike in type are offered as a building block at this premium.
10	const BUILDING_BLOCK_BASE_PREMIUM: u64 = 60;
11	
12	/// A building block is offered for exactly this many alike components.
13	const BUILDING_BLOCK_SIZE: usize = 3;
14	
15	/// The kind of magical item the MHPCO insures.
16	#[derive(PartialEq, Eq, Hash)]
17	pub enum ItemType {
18	    Sword,
19	    Amulet,
20	    Staff,
21	    Potion,
22	    Rune,
23	    Moonstone,
24	}
25	
26	/// An item a customer wishes to insure.
27	pub struct Item {
28	    pub item_type: ItemType,
29	}
30	
31	/// Computes the premium in whole G for the items a customer wishes to insure.
32	pub fn quote(items: &[Item]) -> u64 {
33	    let main_items: u64 = items
34	        .iter()
35	        .filter(|item| !is_component(&item.item_type))
36	        .map(main_item_base_premium)
37	        .sum();
38	    main_items + components_base_premium(items) + PROCESSING_FEE
39	}
40	
41	/// The base premium in G for every component on the policy: the MHPCO prices
42	/// each set of components alike in type on its own.
43	fn components_base_premium(items: &[Item]) -> u64 {
44	    let mut alike_counts: HashMap<&ItemType, usize> = HashMap::new();
45	    for item in items.iter().filter(|item| is_component(&item.item_type)) {
46	        *alike_counts.entry(&item.item_type).or_default() += 1;
47	    }
48	    alike_counts.values().copied().map(alike_base_premium).sum()
49	}
50	
51	/// The base premium in G for one set of components alike in type: the MHPCO
52	/// offers a building block wherever the customer brings exactly three.
53	fn alike_base_premium(alike: usize) -> u64 {
54	    if alike == BUILDING_BLOCK_SIZE {
55	        BUILDING_BLOCK_BASE_PREMIUM
56	    } else {
57	        alike as u64 * COMPONENT_BASE_PREMIUM
58	    }
59	}
60	
61	/// Components, such as runes and moonstones, are the items the MHPCO prices
62	/// uniformly and offers as building blocks.
63	fn is_component(item_type: &ItemType) -> bool {
64	    matches!(item_type, ItemType::Rune | ItemType::Moonstone)
65	}
66	
67	/// The base premium in G the MHPCO charges for one item, straight from its
68	/// price list. `quote` calls this for main items only; components reach their
69	/// uniform premium through `components_base_premium`, which prices a whole
70	/// alike group and so can offer a building block.
71	fn main_item_base_premium(item: &Item) -> u64 {
72	    match item.item_type {
73	        ItemType::Sword => 100,
74	        ItemType::Amulet => 60,
75	        ItemType::Staff => 80,
76	        ItemType::Potion => 40,
77	        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
78	    }
79	}
